const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const gobiDesert = ee.Geometry.Point(103.43, 42.58).buffer(50000); // 50km radius around a central point in Gobi Desert

  const date2019_start = '2019-02-01';
  const date2019_end = '2019-02-28';
  const date2020_start = '2020-02-01';
  const date2020_end = '2020-02-29';

  const AOD_BAND = 'Optical_Depth_055'; // AOD at 550nm, scaled by 1000

  // Function to mask invalid AOD values
  function maskAOD(image) {
    // Values are scaled by 1000. Valid AOD range is generally 0-5.
    // Fill value is -9999.
    const aod = image.select(AOD_BAND);
    const validAod = aod.gte(0).and(aod.lte(5000)); // AOD * 1000, so 0-5
    return image.updateMask(validAod);
  }

  // 2. Data Acquisition & Check
  let collection2019 = ee.ImageCollection('MODIS/006/MCD19A2_GRANULES')
    .filterBounds(gobiDesert)
    .filterDate(date2019_start, date2019_end)
    .map(maskAOD);

  let collection2020 = ee.ImageCollection('MODIS/006/MCD19A2_GRANULES')
    .filterBounds(gobiDesert)
    .filterDate(date2020_start, date2020_end)
    .map(maskAOD);

  const size2019 = await collection2019.size().getInfo();
  const size2020 = await collection2020.size().getInfo();

  if (size2019 === 0 || size2020 === 0) {
    console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);
    console.log("C1");
    return;
  }

  // Reduce to a single image for each period (mean composite)
  const img2019 = collection2019.mean();
  const img2020 = collection2020.mean();

  // 3. Processing (Calculate pixel count to detect C2)
  const scale = 1000; // MODIS resolution is 1km

  const pixelCount2019 = await img2019.select(AOD_BAND)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: gobiDesert,
      scale: scale,
      maxPixels: 1e9
    })
    .get(AOD_BAND)
    .getInfo();

  const pixelCount2020 = await img2020.select(AOD_BAND)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: gobiDesert,
      scale: scale,
      maxPixels: 1e9
    })
    .get(AOD_BAND)
    .getInfo();

  if (pixelCount2019 === 0 || pixelCount2020 === 0) {
    console.log(`2019 Images: ${size2019}, Valid Pixels 2019: ${pixelCount2019}`);
    console.log(`2020 Images: ${size2020}, Valid Pixels 2020: ${pixelCount2020}`);
    console.log("C2");
    return;
  }

  // 4. Calculation
  const meanAOD2019_scaled = await img2019.select(AOD_BAND)
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: gobiDesert,
      scale: scale,
      maxPixels: 1e9
    })
    .get(AOD_BAND)
    .getInfo();

  const meanAOD2020_scaled = await img2020.select(AOD_BAND)
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: gobiDesert,
      scale: scale,
      maxPixels: 1e9
    })
    .get(AOD_BAND)
    .getInfo();

  // 5. Validation & Final Answer
  if (meanAOD2019_scaled === null || isNaN(meanAOD2019_scaled) ||
      meanAOD2020_scaled === null || isNaN(meanAOD2020_scaled)) {
    console.log(`2019 AOD (scaled): ${meanAOD2019_scaled}, 2020 AOD (scaled): ${meanAOD2020_scaled}`);
    console.log("C3");
    return;
  }

  // Unscale the AOD values (divide by 1000)
  const meanAOD2019 = meanAOD2019_scaled / 1000;
  const meanAOD2020 = meanAOD2020_scaled / 1000;

  console.log(`2019 Images: ${size2019}, Valid Pixels: ${pixelCount2019}, Mean AOD: ${meanAOD2019:.4f}`);
  console.log(`2020 Images: ${size2020}, Valid Pixels: ${pixelCount2020}, Mean AOD: ${meanAOD2020:.4f}`);

  if (meanAOD2020 > meanAOD2019) {
    console.log("A"); // Yes, AOD was higher in February 2020
  } else {
    console.log("B"); // No, AOD was not higher in February 2020
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
